77: func generateTasks(args []string) {
78: 	flags := flag.NewFlagSet("gentasks", flag.ExitOnError)
79: 	leakageMode := flags.Bool("leakage", false, "generate the leakage task catalogue")
80: 	if err := flags.Parse(args); err != nil {
81: 		os.Exit(2)
82: 	}
83: 	path := "BENCHMARK_TASKS.json"
84: 	catalog := runner.GenerateCatalog()
85: 	if *leakageMode {
86: 		path = "BENCHMARK_LEAKAGE_TASKS.json"
87: 		catalog = runner.GenerateLeakageCatalog()
88: 	}
89: 	if err := runner.WriteCatalog(path, catalog); err != nil {
90: 		fmt.Fprintln(os.Stderr, err)
91: 		os.Exit(1)
92: 	}
93: 	fmt.Printf("wrote %s with %d tasks\n", path, len(catalog.Tasks))
94: }
