96: func run(args []string) {
97: 	flags := flag.NewFlagSet("run", flag.ExitOnError)
98: 	mode := flags.String("mode", "pilot", "experiment mode")
99: 	limit := flags.Int("limit", 0, "optional per-model task limit")
100: 	output := flags.String("output", "", "results directory")
101: 	binary := flags.String("binary", "opencode", "OpenCode executable")
102: 	tasksPath := flags.String("tasks", "BENCHMARK_TASKS.json", "task catalogue")
103: 	if err := flags.Parse(args); err != nil {
104: 		os.Exit(2)
105: 	}
106: 
