111: 	}
112: 	models := runner.DefaultModels()
113: 	tasks := append([]runner.Task{}, catalog.Tasks...)
114: 
115: 	random := rand.New(rand.NewSource(20261126))
116: 	random.Shuffle(len(tasks), func(i, j int) { tasks[i], tasks[j] = tasks[j], tasks[i] })
117: 
118: 	activeConditions := []condition{conditions[0], conditions[3]}
119: 	if *mode == "leakage" {
120: 		activeConditions = conditions
121: 	}
122: 	if *mode == "full" {
123: 		models = models[:4]
124: 	} else if *mode == "pilot" {
125: 		models = models[:2]
126: 		tasks = tasks[:2]
127: 	} else if *mode != "leakage" {
128: 		fmt.Fprintf(os.Stderr, "unknown mode %q\n", *mode)
129: 		os.Exit(2)
130: 	}
131: 	if *mode == "leakage" {
132: 		tasks = tasks[:20]
133: 	}
134: 	if *limit > 0 && *limit < len(tasks) {
135: 		tasks = tasks[:*limit]
136: 	}
137: 
138: 	outputDir := *output
139: 	if outputDir == "" {
140: 		outputDir = filepath.Join("BENCHMARK", "results", *mode)
141: 	}
142: 	workspaceRoot := filepath.Join("BENCHMARK", "datasets", "workspaces", *mode)
143: 	if err := os.MkdirAll(outputDir, 0o755); err != nil {
144: 		fmt.Fprintln(os.Stderr, err)
145: 		os.Exit(1)
146: 	}
147: 	if err := os.MkdirAll(workspaceRoot, 0o755); err != nil {
148: 		fmt.Fprintln(os.Stderr, err)
149: 		os.Exit(1)
150: 	}
151: 
152: 	payloads := make(map[string]string)
153: 	for _, item := range activeConditions {
154: 		payload, err := runner.InstructionPayload(item.Format, item.Delimiters)
155: 		if err != nil {
156: 			fmt.Fprintln(os.Stderr, err)
157: 			os.Exit(1)
158: 		}
159: 		payloads[item.Name] = payload
160: 	}
161: 
162: 	planned := len(models) * len(activeConditions) * len(tasks)
163: 	completed := 0
164: 	failed := 0
165: 	for _, model := range models {
166: 		for _, item := range activeConditions {
167: 			for _, task := range tasks {
