391: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
392: func RunOne(request Request) (RunRecord, error) {
393: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
394: 		return RunRecord{}, err
395: 	}
396: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
397: 	recordPath := filepath.Join(request.OutputDir, id+".json")
398: 	if existing, err := os.ReadFile(recordPath); err == nil {
399: 		var record RunRecord
400: 		if json.Unmarshal(existing, &record) == nil && record.Success {
401: 			return record, nil
402: 		}
403: 	}
404: 
405: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
406: 	if err != nil {
407: 		return RunRecord{}, err
408: 	}
409: 	binary := request.OpenCodeBinary
410: 	if binary == "" {
411: 		binary = "opencode"
412: 	}
413: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
414: 
415: 	timeout := request.Timeout
416: 	if timeout <= 0 {
417: 		timeout = 10 * time.Minute
418: 	}
419: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
420: 	defer cancel()
421: 
422: 	args := []string{
423: 		"run",
424: 		"--model", request.Model.ID,
425: 		"--format", "json",
426: 		"--auto",
427: 		"--archived",
428: 		"--title", "ail-bench-"+id,
429: 		prompt,
430: 	}
431: 	cmd := exec.CommandContext(ctx, binary, args...)
432: 	cmd.Dir = workDir
433: 	var stdout, stderr bytes.Buffer
434: 	cmd.Stdout = &stdout
435: 	cmd.Stderr = &stderr
436: 
437: 	record := RunRecord{
438: 		ID:         id,
439: 		TaskID:     request.Task.ID,
440: 		Category:   request.Task.Category,
441: 		Model:      request.Model.ID,
442: 		Format:     request.Format,
443: 		Delimiters: request.Delimiters,
444: 		Condition:  request.Condition,
445: 		StartedAt:  time.Now().UTC(),
446: 		WorkDir:    workDir,
447: 	}
448: 	runErr := cmd.Run()
449: 	record.FinishedAt = time.Now().UTC()
450: 	record.DurationMS = record.FinishedAt.Sub(record.StartedAt).Milliseconds()
451: 	if runErr != nil {
452: 		record.Error = runErr.Error()
453: 		if stderr.Len() > 0 {
454: 			record.Error += ": " + stderr.String()
455: 		}
456: 	}
457: 	if exitError, ok := runErr.(*exec.ExitError); ok {
458: 		record.ExitCode = exitError.ExitCode()
459: 	}
460: 
461: 	text, tokens, cost, sessionID, toolCalls, eventCount := parseEvents(stdout.Bytes())
462: 	record.Text = text
463: 	record.Tokens = tokens
464: 	record.Cost = cost
465: 	record.SessionID = sessionID
466: 	record.ToolCalls = toolCalls
467: 	record.EventCount = eventCount
468: 	record.Success = runErr == nil && text != ""
469: 	if terms, loadErr := leakage.LoadTerms("AIL_RULES/project-rules.ail"); loadErr == nil {
470: 		record.Leakage = leakage.NewScorer(terms).Score(record.Text, request.Task.ExplicitRuleRequest)
471: 	}
472: 	if err := VerifyTask(&record, request.Task, 0); err != nil {
473: 		record.VerifyOutput = fmt.Sprintf("verification error: %v", err)
474: 	}
475: 	ScoreCompliance(&record, request.Task)
476: 
477: 	rawPath := filepath.Join(request.OutputDir, id+".events.jsonl")
478: 	if err := os.WriteFile(rawPath, stdout.Bytes(), 0o644); err != nil {
479: 		return record, err
480: 	}
481: 	encoded, err := json.MarshalIndent(record, "", "  ")
482: 	if err != nil {
483: 		return record, err
484: 	}
485: 	if err := os.WriteFile(recordPath, append(encoded, '\n'), 0o644); err != nil {
486: 		return record, err
487: 	}
488: 	return record, nil
489: }
