275: // VerifyTask runs the task verification command inside the isolated workspace.
276: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
277: 	if task.VerifyCommand == "" || record.WorkDir == "" {
278: 		return nil
279: 	}
280: 	if timeout <= 0 {
281: 		timeout = 2 * time.Minute
282: 	}
283: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
284: 	defer cancel()
285: 	parts := strings.Fields(task.VerifyCommand)
286: 	if len(parts) == 0 {
287: 		return nil
288: 	}
289: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
290: 	cmd.Dir = record.WorkDir
291: 	output, err := cmd.CombinedOutput()
292: 	record.VerifyOutput = string(output)
293: 	if exitError, ok := err.(*exec.ExitError); ok {
294: 		record.VerifyExitCode = exitError.ExitCode()
295: 	} else if err != nil {
296: 		record.VerifyExitCode = -1
297: 	}
298: 	record.VerifyPassed = err == nil
299: 	return nil
300: }
301: 
302: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
303: func ScoreCompliance(record *RunRecord, task Task) {
304: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
305: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
306: 	for _, rule := range task.ApplicableRules {
307: 		if !machineRules[rule] {
308: 			continue
309: 		}
310: 		result.Checked++
311: 		passed := false
312: 		switch rule {
313: 		case "R001":
314: 			passed = !workspaceContainsDash(record.WorkDir)
315: 		case "R002":
316: 			passed = !workspaceHasLargeFile(record.WorkDir)
317: 		case "R003":
318: 			passed = record.VerifyPassed
319: 		}
320: 		if passed {
321: 			result.Followed++
322: 		} else {
323: 			result.Violated = append(result.Violated, rule)
324: 		}
325: 	}
326: 	if result.Checked > 0 {
327: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
328: 	}
329: 	record.Compliance = result
330: }
