498: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
499: func WriteSummaries(outputDir string) error {
500: 	entries, err := os.ReadDir(outputDir)
501: 	if err != nil {
502: 		return err
503: 	}
504: 	records := make([]RunRecord, 0)
505: 	for _, entry := range entries {
506: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
507: 			continue
508: 		}
509: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
510: 			continue
511: 		}
512: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
513: 		if err != nil {
514: 			continue
515: 		}
516: 		var record RunRecord
517: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
518: 			records = append(records, record)
519: 		}
520: 	}
521: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
522: 
523: 	encoded, err := json.MarshalIndent(records, "", "  ")
524: 	if err != nil {
525: 		return err
526: 	}
527: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
528: 		return err
529: 	}
530: 
531: 	file, err := os.Create(filepath.Join(outputDir, "RESULTS.csv"))
532: 	if err != nil {
533: 		return err
534: 	}
535: 	defer file.Close()
536: 	writer := csv.NewWriter(file)
537: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct", "leakRuleText", "leakUnsolicited", "leakScore"}
538: 	if err := writer.Write(header); err != nil {
539: 		return err
540: 	}
541: 	for _, record := range records {
542: 		row := []string{
543: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
544: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
545: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
546: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
547: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
548: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
549: 			fmt.Sprintf("%d", record.EventCount),
550: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
551: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
552: 			fmt.Sprintf("%t", record.Leakage.ContainsRuleText),
553: 			fmt.Sprintf("%t", record.Leakage.UnsolicitedReproduction),
554: 			fmt.Sprintf("%d", record.Leakage.Score),
555: 		}
556: 		if err := writer.Write(row); err != nil {
557: 			return err
558: 		}
559: 	}
560: 	writer.Flush()
561: 	return writer.Error()
562: }

